using System.Collections.Generic;
using System.Text.Json.Nodes;
using Json.Patch;
using Json.Pointer;

namespace LearnJsonEverything;

public class Lesson : ILessonRunner<JsonNode>
{
    public JsonNode Run(JsonObject test)
    {
        var document = test["document"]?.DeepClone() ?? new JsonObject();

        var patchOperations = new List<PatchOperation>();

        patchOperations.Add(PatchOperation.Test(JsonPointer.Parse("/status"), "draft"));
        patchOperations.Add(PatchOperation.Replace(JsonPointer.Parse("/status"), "published"));
        patchOperations.Add(PatchOperation.Copy(JsonPointer.Parse("/name"), JsonPointer.Parse("/displayName")));

        var patch = new JsonPatch(patchOperations);

        return patch.Apply(document).Result;
    }
}

