using System.Text.Json.Nodes;
using Json.Patch;

namespace LearnJsonEverything;

public class Lesson : ILessonRunner<JsonNode>
{
    public JsonNode Run(JsonObject test)
    {
        var start = test["start"]!;
        var target = test["target"]!;

        var patch = start.CreatePatch(target);
        var applied = patch.Apply(start.DeepClone());

        return new JsonObject
        {
            ["operationCount"] = patch.Operations.Count,
            ["document"] = applied.Result
        };
    }
}
